{
  "compilerOptions": {
    "baseUrl": "./",
    "checkJs": true,
    "target": "ES2020",
    "noImplicitAny": true,
    "noUncheckedIndexedAccess": true,
    "strictNullChecks": true,
    "types": ["./global.d.ts", "./standard-events.d.ts"],
    "paths": {
      "@theme/*": ["./*"],
      "@shopify/events": ["./standard-events"]
    }
  }
}

import { ResizeNotifier, prefersReducedMotion, yieldToMainThread } from '@theme/utilities';
import { Component } from '@theme/component';
import { getScrollContainer, getScrollTop } from '@theme/scroll-container';

/**
 * A custom element that automatically sizes text to fit its container width.
 */
class JumboText extends Component {
  connectedCallback() {
    super.connectedCallback();
    this.#setIntersectionObserver();

    // We need window listener to account for flex containers not shrinking until we reset the font size.
    window.addEventListener('resize', this.#windowResizeListener);

    // A web font can finish loading after the first measurement, and before the resize observer's
    // first notification, which it ignores. Re-measure when fonts load so the text isn't left sized for the fallback font.
    document.fonts?.addEventListener('loadingdone', this.#fontsLoadedListener);
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this.#resizeObserver.disconnect();
    this.#intersectionObserver?.disconnect();

    window.removeEventListener('resize', this.#windowResizeListener);
    document.fonts?.removeEventListener('loadingdone', this.#fontsLoadedListener);
  }

  #firstResize = true;

  /**
   * Sets the intersection observer to calculate the optimal font size when the text is in view.
   */
  #setIntersectionObserver() {
    // The threshold could be different based on the repetition of the animation.
    this.#intersectionObserver = new IntersectionObserver(
      (entries) => {
        // We observe a single element, so we only need the latest entry.
        const entry = entries[entries.length - 1];

        if (!entry) {
          return;
        }

        // Initial calculation
        if (entry.isIntersecting && this.#firstResize) {
          this.#handleResize(entry.boundingClientRect.width);
        }

        if (this.dataset.textEffect && this.dataset.textEffect !== 'none' && !prefersReducedMotion()) {
          if (entry.intersectionRatio >= 0.3) {
            this.classList.add('ready');
            if (this.dataset.animationRepeat === 'false') {
              this.#intersectionObserver?.unobserve(entry.target);
            }
            // We need to wait for resize recalculations to apply before triggering transitions.
            yieldToMainThread().then(() => {
              this.classList.add('jumbo-text-visible');
            });
          } else {
            this.classList.remove('ready', 'jumbo-text-visible');
          }
        }
      },
      { threshold: [0, 0.3] }
    );

    this.#intersectionObserver?.observe(this);
  }

  /**
   * Calculates the optimal font size to make the text fit the container.
   * @param {number} containerWidth - The width of the jumbo-text element.
   */
  #calculateOptimalFontSize = (containerWidth) => {
    const { widestChild: firstPassWidestChild, widestChildWidth: firstPassWidestChildWidth } = this.#findWidestChild();
    if (!firstPassWidestChild || !firstPassWidestChildWidth) {
      return;
    }

    const currentFontSize = parseFloat(window.getComputedStyle(firstPassWidestChild).fontSize);
    const firstPassFontSize = Math.round(((currentFontSize * containerWidth) / firstPassWidestChildWidth) * 100) / 100;

    // Disconnect the resize observer
    this.#resizeObserver.disconnect();

    this.style.fontSize = this.#clampFontSize(firstPassFontSize);

    // The way the text grows is mostly proportional, but not fully linear.
    // Doing a single pass was good enough in 95% of cases, but we need a second one to dial in the final value.
    const { widestChild: secondPassWidestChild, widestChildWidth: secondPassWidestChildWidth } =
      this.#findWidestChild();
    if (!secondPassWidestChild || !secondPassWidestChildWidth) {
      return;
    }

    // The second pass refines the font size based on actual rendered width.
    // The -0.15 was chosen by trial and error. It doesn't influence large font sizes much, but helps smaller ones fit better.
    // Use Math.min to ensure we never increase beyond the first pass — font rendering is not
    // perfectly proportional (scaling by 2x doesn't always produce exactly 2x wider text due
    // to pixel rounding), so the second pass can overshoot.
    const secondPassFontSize = Math.min(
      Math.floor(((firstPassFontSize * containerWidth) / secondPassWidestChildWidth) * 100) / 100 - 0.15,
      firstPassFontSize
    );

    if (secondPassFontSize !== firstPassFontSize) {
      this.style.fontSize = this.#clampFontSize(secondPassFontSize);
    }

    this.classList.add('ready');

    this.#resizeObserver.observe(this);
  };

  #findWidestChild = () => {
    let widestChild = null;
    let widestChildWidth = 0;

    for (const child of this.children) {
      if (!(child instanceof HTMLElement)) {
        continue;
      }

      const { width: childWidth } = child.getBoundingClientRect();

      if (!widestChild || childWidth > widestChildWidth) {
        widestChildWidth = childWidth;
        widestChild = child;
      }
    }
    return { widestChild, widestChildWidth };
  };

  /**
   * Clamps the font size between a minimum and maximum value.
   * @param {number} fontSize - The font size to clamp.
   * @returns {string} The clamped font size with pixels suffix.
   */
  #clampFontSize = (fontSize) => {
    const minFontSize = 1;
    const maxFontSize = 500;

    return `${Math.min(Math.max(fontSize, minFontSize), maxFontSize)}px`;
  };

  /**
   * @param {number | undefined} containerWidth - The width of the <jumbo-text> element.
   */
  #handleResize = (containerWidth = undefined) => {
    // Check for empty text
    if (!this.textContent?.trim()) {
      return;
    }

    if (containerWidth === undefined) {
      containerWidth = this.offsetWidth;
    }

    if (containerWidth <= 0) return;

    // Reset font size to make sure we allow the container to shrink if it needs to.
    if (!this.#firstResize) {
      this.classList.remove('ready');
      this.style.fontSize = '';
    }

    this.#calculateOptimalFontSize(containerWidth);

    this.#firstResize = false;

    if (this.dataset.capText === 'true') {
      return;
    }

    // We assume that the component won't be at the bottom of the page unless it's inside the last section.
    const allSections = Array.from(document.querySelectorAll('.shopify-section'));
    const lastSection = allSections[allSections.length - 1];

    if (lastSection && !lastSection.contains(this)) {
      return;
    }

    // Check if jumbo text is close to the bottom of the page. If it is, then use `cap text` instead of `cap alphabetic`.
    // This reserves space for descender characters so they don't overflow and cause extra space at the bottom of the page.
    const rect = this.getBoundingClientRect();
    const bottom = rect.bottom + getScrollTop();
    const distanceFromBottom = getScrollContainer().scrollHeight - bottom;
    this.dataset.capText = (distanceFromBottom <= 100).toString();
  };

  #windowResizeListener = () => this.#handleResize();

  #fontsLoadedListener = () => {
    // Before the first measurement, the intersection observer does the initial sizing.
    if (this.#firstResize) return;

    this.#handleResize();
  };

  #resizeObserver = new ResizeNotifier((entries) => this.#handleResize(entries[0]?.borderBoxSize?.[0]?.inlineSize));
  /**
   * @type {IntersectionObserver | null}
   */
  #intersectionObserver = null;
}

// Register once
if (!customElements.get('jumbo-text')) {
  customElements.define('jumbo-text', JumboText);
}

/* Launchify section library — shared styles */
.lf-section {
  --lf-pad-x: clamp(16px, 4vw, 56px);
  --lf-pad-y: clamp(48px, 7vw, 96px);
  --lf-radius: 20px;
  --lf-radius-sm: 12px;
  background: var(--lf-sec-bg, var(--lf-bg));
  color: var(--lf-sec-fg, var(--lf-fg));
  padding: var(--lf-pad-y) 0;
  font-family: var(--font-body--family);
}
.lf-section *, .lf-section *::before, .lf-section *::after { box-sizing: border-box; }
.lf-scheme-light { --lf-sec-bg: var(--lf-bg); --lf-sec-fg: var(--lf-fg); --lf-sec-card: var(--lf-soft); }
.lf-scheme-soft { --lf-sec-bg: var(--lf-soft); --lf-sec-fg: var(--lf-fg); --lf-sec-card: var(--lf-bg); }
.lf-scheme-dark { --lf-sec-bg: var(--lf-fg); --lf-sec-fg: var(--lf-bg); --lf-sec-card: rgb(255 255 255 / .08); }
.lf-scheme-accent { --lf-sec-bg: var(--lf-accent); --lf-sec-fg: var(--lf-on-accent); --lf-sec-card: rgb(255 255 255 / .14); }

.lf-container { max-width: 1360px; margin: 0 auto; padding: 0 var(--lf-pad-x); }
.lf-eyebrow {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 12px; font-weight: 600; letter-spacing: .12em; text-transform: uppercase;
  opacity: .75; margin: 0 0 14px;
}
.lf-eyebrow--pill { opacity: 1; padding: 6px 12px; border-radius: 99px; background: var(--lf-sec-card); }
.lf-h1, .lf-h2, .lf-h3 { font-family: var(--font-heading--family); font-weight: var(--font-heading--weight, 700); letter-spacing: -0.025em; margin: 0; color: inherit; text-wrap: balance; }
.lf-h1 { font-size: clamp(40px, 5.6vw, 76px); line-height: 1.02; }
.lf-h2 { font-size: clamp(30px, 3.6vw, 48px); line-height: 1.08; }
.lf-h3 { font-size: clamp(18px, 1.6vw, 22px); line-height: 1.25; letter-spacing: -0.01em; }
.lf-h1 em, .lf-h2 em { font-style: normal; color: var(--lf-accent); }
.lf-scheme-accent .lf-h1 em, .lf-scheme-accent .lf-h2 em { color: inherit; text-decoration: underline; text-decoration-thickness: 3px; text-underline-offset: 6px; }
.lf-lead { font-size: clamp(16px, 1.25vw, 18px); line-height: 1.6; opacity: .82; max-width: 52ch; margin: 18px 0 0; }
.lf-head { display: flex; align-items: end; justify-content: space-between; gap: 24px; margin-bottom: clamp(28px, 4vw, 48px); }
.lf-head--center { flex-direction: column; align-items: center; text-align: center; }
.lf-head--center .lf-lead { margin-inline: auto; }
.lf-link { color: inherit; font-size: 13px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; text-decoration: underline; text-underline-offset: 5px; white-space: nowrap; }

.lf-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 10px;
  min-height: 54px; padding: 0 30px; border-radius: 99px;
  background: var(--lf-fg); color: var(--lf-bg);
  font-size: 14px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; text-decoration: none;
  border: 1.5px solid var(--lf-fg); cursor: pointer;
  transition: transform .2s ease, background .2s ease, color .2s ease;
}
.lf-btn:hover { transform: translateY(-2px); background: var(--lf-accent); border-color: var(--lf-accent); color: var(--lf-on-accent); }
.lf-btn--ghost { background: transparent; color: inherit; border-color: currentColor; }
.lf-btn--light { background: var(--lf-bg); color: var(--lf-fg); border-color: var(--lf-bg); }
.lf-btn--block { width: 100%; }
.lf-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 30px; }

.lf-stars { display: inline-flex; gap: 2px; color: var(--lf-star, #f5b301); }
.lf-star--off { opacity: .25; }
.lf-rating { display: inline-flex; align-items: center; gap: 10px; font-size: 14px; font-weight: 500; }
.lf-placeholder { width: 100%; height: 100%; background: var(--lf-soft); fill: currentColor; opacity: .5; }

/* Countdown / announcement bar */
.lf-bar { background: var(--lf-fg); color: var(--lf-bg); padding: 10px var(--lf-pad-x, 16px); display: flex; align-items: center; justify-content: center; gap: 18px; flex-wrap: wrap; font-family: var(--font-body--family); text-align: center; }
.lf-bar__text { font-size: 13px; line-height: 1.35; letter-spacing: .04em; }
.lf-bar__text strong { color: var(--lf-accent-bright, var(--lf-accent)); font-weight: 700; text-transform: uppercase; }
.lf-bar__timer { display: inline-flex; gap: 6px; }
.lf-bar__unit { display: grid; place-items: center; min-width: 38px; padding: 4px 6px; border-radius: 6px; background: rgb(255 255 255 / .12); font-variant-numeric: tabular-nums; font-weight: 700; font-size: 15px; line-height: 1; }
.lf-bar__unit small { font-size: 8px; font-weight: 500; opacity: .7; letter-spacing: .1em; margin-top: 3px; }

/* Hero */
.lf-hero { padding: 0; }
.lf-hero__grid { display: grid; grid-template-columns: 1fr 1.05fr; min-height: min(86vh, 760px); }
.lf-hero__content { display: flex; flex-direction: column; justify-content: center; padding: clamp(40px, 6vw, 88px) var(--lf-pad-x); max-width: 680px; margin-left: auto; width: 100%; }
.lf-hero__media { position: relative; overflow: hidden; min-height: 420px; }
.lf-hero__media img, .lf-hero__media svg { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.lf-hero__badge { position: absolute; left: 24px; bottom: 24px; padding: 10px 16px; border-radius: 99px; background: var(--lf-bg); color: var(--lf-fg); font-size: 13px; font-weight: 600; box-shadow: 0 10px 30px rgb(0 0 0 / .12); }
.lf-trustcard { display: flex; gap: 14px; align-items: center; margin-top: 34px; padding: 16px 18px; border-radius: var(--lf-radius-sm); background: var(--lf-sec-card); max-width: 430px; font-size: 14px; line-height: 1.45; }
.lf-trustcard__icon { flex: none; width: 42px; height: 42px; border-radius: 50%; display: grid; place-items: center; background: var(--lf-accent); color: var(--lf-on-accent); font-size: 20px; }
.lf-trustcard p { margin: 2px 0 0; opacity: .8; }
.lf-perks { display: flex; flex-wrap: wrap; gap: 8px 20px; margin: 22px 0 0; padding: 0; list-style: none; font-size: 14px; }
.lf-perks li::before { content: "✓"; margin-right: 8px; color: var(--lf-accent); font-weight: 700; }

/* Marquee */
.lf-marquee { overflow: hidden; padding: 16px 0; background: var(--lf-sec-bg); color: var(--lf-sec-fg); }
.lf-marquee__track { display: flex; width: max-content; animation: lf-scroll var(--lf-speed, 30s) linear infinite; }
.lf-marquee__item { display: inline-flex; align-items: center; gap: 28px; padding-right: 28px; white-space: nowrap; font-family: var(--font-heading--family); font-size: clamp(15px, 1.5vw, 20px); font-weight: 600; text-transform: uppercase; letter-spacing: .04em; }
.lf-marquee__item::after { content: "✦"; color: var(--lf-accent); }
.lf-scheme-accent .lf-marquee__item::after { color: inherit; }
@keyframes lf-scroll { to { transform: translateX(-50%); } }
@media (prefers-reduced-motion: reduce) { .lf-marquee__track { animation: none; } }

/* Product cards */
.lf-grid { display: grid; grid-template-columns: repeat(var(--lf-cols, 4), minmax(0, 1fr)); gap: clamp(12px, 1.6vw, 24px); }
.lf-card { display: flex; flex-direction: column; color: inherit; text-decoration: none; }
.lf-card__media { position: relative; aspect-ratio: 4 / 5; border-radius: var(--lf-radius); overflow: hidden; background: var(--lf-sec-card); }
.lf-card__media img, .lf-card__media svg { width: 100%; height: 100%; object-fit: cover; transition: transform .6s ease; }
.lf-card:hover .lf-card__media img { transform: scale(1.04); }
.lf-badges { position: absolute; top: 12px; left: 12px; right: 12px; display: flex; justify-content: space-between; gap: 6px; pointer-events: none; }
.lf-badge { padding: 6px 10px; border-radius: 99px; font-size: 11px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; background: var(--lf-bg); color: var(--lf-fg); }
.lf-badge--sale { background: var(--lf-fg); color: var(--lf-bg); }
.lf-card__body { padding: 16px 4px 0; display: flex; flex-direction: column; gap: 6px; flex: 1; }
.lf-card__rating { display: flex; align-items: center; gap: 6px; font-size: 12px; opacity: .85; }
.lf-card__title { font-family: var(--font-heading--family); font-size: 17px; font-weight: 600; line-height: 1.3; margin: 0; }
.lf-card__sub { font-size: 14px; opacity: .7; margin: 0; }
.lf-price { display: flex; align-items: baseline; gap: 8px; font-weight: 700; font-size: 16px; margin-top: 2px; }
.lf-price s { font-weight: 400; opacity: .5; font-size: 14px; }
.lf-card .lf-btn { margin-top: auto; min-height: 46px; font-size: 13px; }
.lf-card__body > :last-child.lf-btn { margin-top: 14px; }

/* Reviews */
.lf-scroller { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(280px, 1fr); gap: 18px; overflow-x: auto; scroll-snap-type: x mandatory; padding-bottom: 8px; scrollbar-width: thin; }
.lf-scroller > * { scroll-snap-align: start; }
.lf-review { display: flex; flex-direction: column; gap: 12px; padding: 26px; border-radius: var(--lf-radius); background: var(--lf-sec-card); min-height: 280px; }
.lf-review__title { font-family: var(--font-heading--family); font-size: 18px; font-weight: 600; margin: 0; line-height: 1.3; }
.lf-review__text { font-size: 15px; line-height: 1.6; opacity: .82; margin: 0; flex: 1; }
.lf-review__author { display: flex; align-items: center; gap: 10px; font-size: 14px; font-weight: 600; }
.lf-review__author img { width: 40px; height: 40px; border-radius: 50%; object-fit: cover; }
.lf-verified { font-size: 12px; font-weight: 500; opacity: .65; }
.lf-verified::before { content: "✓ "; color: var(--lf-accent); font-weight: 700; }
.lf-scoreline { display: flex; align-items: center; gap: 12px; justify-content: center; margin-top: 14px; font-size: 15px; }
.lf-scoreline strong { font-size: 20px; }

/* Categories */
.lf-cats { display: grid; grid-template-columns: repeat(var(--lf-cols, 4), minmax(0, 1fr)); gap: clamp(12px, 1.6vw, 24px); }
.lf-cat { position: relative; display: block; aspect-ratio: 3 / 4; border-radius: var(--lf-radius); overflow: hidden; color: #fff; text-decoration: none; }
.lf-cat img, .lf-cat svg { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; transition: transform .6s ease; }
.lf-cat:hover img { transform: scale(1.05); }
.lf-cat::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, transparent 45%, rgb(0 0 0 / .55)); }
.lf-cat__label { position: absolute; left: 20px; right: 20px; bottom: 20px; z-index: 1; display: flex; flex-direction: column; gap: 4px; }
.lf-cat__label strong { font-family: var(--font-heading--family); font-size: clamp(22px, 2.2vw, 30px); letter-spacing: -0.02em; }
.lf-cat__label span { font-size: 12px; font-weight: 600; letter-spacing: .1em; text-transform: uppercase; }

/* Spotlight */
.lf-split { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(28px, 5vw, 80px); align-items: center; }
.lf-split--reverse .lf-split__media { order: 2; }
.lf-split__media { position: relative; aspect-ratio: 4 / 5; border-radius: calc(var(--lf-radius) * 1.4); overflow: hidden; background: var(--lf-sec-card); }
.lf-split__media img, .lf-split__media svg { width: 100%; height: 100%; object-fit: cover; }
.lf-bullets { list-style: none; padding: 0; margin: 26px 0 0; display: grid; gap: 14px; }
.lf-bullets li { display: flex; gap: 14px; align-items: flex-start; font-size: 16px; line-height: 1.5; }
.lf-bullets li::before { content: "✓"; flex: none; display: grid; place-items: center; width: 26px; height: 26px; border-radius: 50%; background: var(--lf-accent); color: var(--lf-on-accent); font-size: 13px; font-weight: 700; }
.lf-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 16px; margin-top: 30px; padding-top: 26px; border-top: 1px solid color-mix(in srgb, currentColor 15%, transparent); }
.lf-stat strong { display: block; font-family: var(--font-heading--family); font-size: clamp(30px, 3vw, 42px); letter-spacing: -0.03em; color: var(--lf-accent); line-height: 1; }
.lf-scheme-accent .lf-stat strong, .lf-scheme-dark .lf-stat strong { color: inherit; }
.lf-stat span { display: block; font-size: 13px; line-height: 1.4; opacity: .75; margin-top: 8px; }

/* Bundles */
.lf-bundles { display: grid; grid-template-columns: repeat(var(--lf-cols, 3), minmax(0, 1fr)); gap: clamp(14px, 2vw, 28px); }
.lf-bundle { display: flex; flex-direction: column; border-radius: var(--lf-radius); overflow: hidden; background: var(--lf-sec-card); color: inherit; text-decoration: none; }
.lf-bundle__media { position: relative; aspect-ratio: 5 / 4; overflow: hidden; }
.lf-bundle__media img, .lf-bundle__media svg { width: 100%; height: 100%; object-fit: cover; }
.lf-bundle__body { padding: 22px; display: flex; flex-direction: column; gap: 8px; flex: 1; }
.lf-bundle__body p { margin: 0; font-size: 14px; line-height: 1.55; opacity: .78; }
.lf-bundle__value { font-size: 13px; opacity: .7; }
.lf-bundle .lf-btn { margin-top: 14px; }

/* Benefits */
.lf-benefits { display: grid; grid-template-columns: repeat(var(--lf-cols, 4), minmax(0, 1fr)); gap: clamp(14px, 2vw, 24px); }
.lf-benefit { padding: 28px 24px; border-radius: var(--lf-radius); background: var(--lf-sec-card); }
.lf-benefit__icon { width: 52px; height: 52px; display: grid; place-items: center; border-radius: 16px; background: var(--lf-accent); color: var(--lf-on-accent); font-size: 24px; margin-bottom: 18px; }
.lf-benefit p { margin: 8px 0 0; font-size: 15px; line-height: 1.55; opacity: .78; }
.lf-benefits--strip { gap: 0; border-block: 1px solid color-mix(in srgb, currentColor 14%, transparent); }
.lf-benefits--strip .lf-benefit { background: none; border-radius: 0; display: flex; gap: 14px; align-items: center; padding: 22px 20px; }
.lf-benefits--strip .lf-benefit + .lf-benefit { border-left: 1px solid color-mix(in srgb, currentColor 14%, transparent); }
.lf-benefits--strip .lf-benefit__icon { margin: 0; width: 44px; height: 44px; font-size: 20px; flex: none; }
.lf-benefits--strip .lf-h3 { font-size: 15px; }
.lf-benefits--strip p { margin-top: 2px; font-size: 13px; }

/* Expert */
.lf-quote { font-family: var(--font-heading--family); font-size: clamp(22px, 2.3vw, 32px); line-height: 1.35; letter-spacing: -0.015em; margin: 22px 0 0; }
.lf-quote::before { content: "“"; display: block; font-size: 72px; line-height: .6; color: var(--lf-accent); margin-bottom: 8px; }
.lf-signature { margin-top: 26px; font-size: 14px; line-height: 1.5; }
.lf-signature strong { display: block; font-size: 16px; letter-spacing: .04em; text-transform: uppercase; }
.lf-proof { display: inline-flex; align-items: center; gap: 10px; margin-top: 22px; padding: 10px 16px; border-radius: 99px; background: var(--lf-sec-card); font-size: 14px; }

/* Manifesto */
.lf-manifesto { text-align: center; }
.lf-manifesto .lf-h2 { font-size: clamp(34px, 5vw, 68px); max-width: 18ch; margin-inline: auto; }
.lf-manifesto .lf-lead { margin-inline: auto; max-width: 60ch; }
.lf-manifesto .lf-actions { justify-content: center; }

/* FAQ */
.lf-faq { max-width: 860px; margin: 0 auto; }
.lf-faq details { border-bottom: 1px solid color-mix(in srgb, currentColor 16%, transparent); }
.lf-faq summary { list-style: none; cursor: pointer; display: flex; justify-content: space-between; gap: 20px; padding: 24px 0; font-family: var(--font-heading--family); font-size: clamp(17px, 1.5vw, 20px); font-weight: 600; }
.lf-faq summary::-webkit-details-marker { display: none; }
.lf-faq summary::after { content: "+"; font-size: 26px; line-height: 1; font-weight: 300; transition: transform .2s; }
.lf-faq details[open] summary::after { transform: rotate(45deg); }
.lf-faq__answer { padding: 0 0 24px; font-size: 16px; line-height: 1.65; opacity: .8; max-width: 70ch; }

@media (max-width: 989px) {
  .lf-hero__grid { grid-template-columns: 1fr; min-height: 0; }
  .lf-hero__media { order: -1; min-height: 0; aspect-ratio: 4 / 4.2; }
  .lf-hero__content { max-width: none; padding-top: 32px; padding-bottom: 48px; }
  .lf-grid, .lf-cats, .lf-benefits { --lf-cols: 2 !important; }
  .lf-bundles { grid-template-columns: 1fr; }
  .lf-split { grid-template-columns: 1fr; }
  .lf-split--reverse .lf-split__media { order: 0; }
  .lf-head { flex-direction: column; align-items: flex-start; }
  .lf-head--center { align-items: center; }
  .lf-benefits--strip .lf-benefit + .lf-benefit { border-left: 0; }
}
@media (max-width: 560px) {
  .lf-grid { gap: 10px 10px; }
  .lf-card__title { font-size: 15px; }
  .lf-badges { top: 8px; left: 8px; right: 8px; }
  .lf-badge { padding: 5px 8px; font-size: 9px; letter-spacing: .04em; white-space: nowrap; }
  .lf-card .lf-btn { min-height: 42px; padding: 0 12px; font-size: 12px; }
  .lf-benefits { --lf-cols: 1 !important; }
  .lf-benefits--strip { --lf-cols: 2 !important; }
  .lf-benefits--strip .lf-benefit { flex-direction: column; text-align: center; padding: 16px 8px; }
  .lf-bar { gap: 10px; }
}

/* ---------- Product page ---------- */
.lf-pdp-rating { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.lf-pdp-rating .lf-rating { color: inherit; text-decoration: none; font-size: 14px; }
.lf-pdp-rating__count { opacity: .7; text-decoration: underline; text-underline-offset: 3px; }
.lf-pdp-bullets { list-style: none; margin: 4px 0; padding: 0; display: grid; gap: 10px; font-size: 15px; line-height: 1.45; }
.lf-pdp-bullets li { display: flex; gap: 10px; align-items: flex-start; }
.lf-pdp-bullets li::before { content: "✓"; flex: none; display: grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; background: var(--lf-accent); color: var(--lf-on-accent); font-size: 12px; font-weight: 700; }
.lf-pdp-urgency { display: grid; gap: 8px; padding: 14px 16px; border-radius: 14px; background: var(--lf-soft); font-size: 14px; }
.lf-pdp-urgency p { margin: 0; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.lf-pdp-urgency strong { color: var(--lf-accent); }
.lf-dot { width: 9px; height: 9px; border-radius: 50%; background: #e5484d; box-shadow: 0 0 0 0 rgb(229 72 77 / .5); animation: lf-pulse 1.6s infinite; }
@keyframes lf-pulse { 70% { box-shadow: 0 0 0 9px rgb(229 72 77 / 0); } 100% { box-shadow: 0 0 0 0 rgb(229 72 77 / 0); } }
.lf-pdp-trust { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.lf-pdp-trust__item { display: flex; align-items: center; gap: 10px; padding: 12px; border: 1px solid var(--lf-line); border-radius: 12px; font-size: 13px; font-weight: 500; }
.lf-pdp-trust__item span { font-size: 18px; }
.lf-pdp-payments { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 4px; }
.lf-pay { width: 38px; height: 24px; }

.lf-compare { max-width: 820px; margin: 0 auto; border-radius: var(--lf-radius); overflow: hidden; background: var(--lf-sec-card); }
.lf-compare__row { display: grid; grid-template-columns: 1.6fr 1fr 1fr; align-items: center; text-align: center; border-top: 1px solid color-mix(in srgb, currentColor 10%, transparent); }
.lf-compare__row > span { padding: 18px 14px; }
.lf-compare__row > span:first-child { text-align: left; font-weight: 500; }
.lf-compare__row--head { border-top: 0; font-family: var(--font-heading--family); font-weight: 700; }
.lf-compare__us { background: color-mix(in srgb, var(--lf-accent) 12%, transparent); height: 100%; display: grid; place-items: center; }
.lf-compare__row--head .lf-compare__us { background: var(--lf-accent); color: var(--lf-on-accent); }
.lf-yes, .lf-no { display: inline-grid; place-items: center; width: 28px; height: 28px; border-radius: 50%; font-size: 14px; }
.lf-yes { background: var(--lf-accent); color: var(--lf-on-accent); }
.lf-yes--muted { background: color-mix(in srgb, currentColor 18%, transparent); color: inherit; }
.lf-no { color: color-mix(in srgb, currentColor 45%, transparent); }
@media (max-width: 560px) {
  .lf-compare__row > span { padding: 14px 8px; font-size: 14px; }
  .lf-pdp-trust__item { font-size: 12px; padding: 10px; }
}

/* Product descriptions imported from the catalog: keep them compact inside the accordion */
.accordion .details-content .rte h1,
.accordion .details-content .rte h2 { font-size: clamp(19px, 1.6vw, 22px) !important; line-height: 1.25; text-transform: none !important; text-align: left !important; margin: 1.2em 0 .4em; letter-spacing: -0.01em; }
.accordion .details-content .rte h3,
.accordion .details-content .rte h4 { font-size: 16px !important; text-align: left !important; margin: 1em 0 .3em; }
.accordion .details-content .rte p,
.accordion .details-content .rte li { font-size: 15px; line-height: 1.6; text-align: left !important; }
.accordion .details-content .rte > :first-child { margin-top: 0; }

/* Description images: respect the width attribute from the product HTML (Horizon forces width:100% on every img) */
.rte img[width] { width: attr(width px); max-width: 100%; height: auto; }
.rte img[width="70"], .rte img[width="71"] { width: 70px; }
.rte img[width="350"] { width: 350px; }

/* Description videos reuse Horizon's .video-background class, which is absolutely positioned: keep them in the text flow */
.rte .video-background,
.rte .video-background * { position: static; width: 100%; height: auto; overflow: visible; }
.rte video { display: block; max-width: min(340px, 100%); margin-inline: auto; }

/* Horizon renders img as block, so text-align:center on the wrapper no longer centers description icons */
.rte [style*="text-align: center"] img,
.rte [style*="text-align:center"] img { display: block; margin-inline: auto; }

/* Reviews without a verification label: no orphan check mark */
.lf-verified:empty { display: none; }

/* Buyer reviews (public review synthesis + store review app) */
.lf-bs__grid { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); gap: clamp(16px, 2vw, 28px); max-width: 1080px; margin: 0 auto; align-items: start; }
.lf-bs__sources { display: grid; gap: 12px; }
.lf-bs__src { padding: 22px 24px; border-radius: var(--lf-radius); background: var(--lf-sec-card); }
.lf-bs__score { font-family: var(--font-heading--family); font-size: clamp(36px, 4vw, 48px); font-weight: 700; line-height: 1; }
.lf-bs__score span { font-size: .4em; opacity: .55; margin-left: 2px; }
.lf-bs__stars { position: relative; display: inline-block; margin: 10px 0 8px; font-size: 18px; line-height: 1; letter-spacing: 3px; color: color-mix(in srgb, currentColor 18%, transparent); }
.lf-bs__stars::before, .lf-bs__stars::after { content: "★★★★★"; }
.lf-bs__stars::after { position: absolute; left: 0; top: 0; width: var(--lf-pct, 100%); overflow: hidden; white-space: nowrap; color: var(--lf-star, #f5b301); }
.lf-bs__srcname { margin: 0; font-size: 15px; }
.lf-bs__basis { margin: 4px 0 0; font-size: 13px; opacity: .65; }
.lf-bs__body { padding: clamp(22px, 2.6vw, 34px); border-radius: var(--lf-radius); background: var(--lf-sec-card); }
.lf-bs__h3 { margin: 0 0 14px; font-family: var(--font-heading--family); font-size: 20px; font-weight: 600; }
.lf-bs__likes { list-style: none; margin: 0; padding: 0; display: grid; gap: 12px; }
.lf-bs__likes li { position: relative; padding-left: 34px; font-size: 16px; line-height: 1.45; }
.lf-bs__likes li::before { content: "✓"; position: absolute; left: 0; top: -1px; width: 22px; height: 22px; border-radius: 50%; display: grid; place-items: center; font-size: 12px; font-weight: 700; background: var(--lf-accent); color: var(--lf-on-accent); }
.lf-bs__note { margin-top: 22px; padding: 16px 18px; border-radius: var(--lf-radius-sm); border: 1.5px dashed color-mix(in srgb, currentColor 22%, transparent); }
.lf-bs__note strong { display: block; font-size: 12px; letter-spacing: .08em; text-transform: uppercase; margin-bottom: 4px; }
.lf-bs__note p { margin: 0; font-size: 15px; line-height: 1.5; opacity: .85; }
.lf-bs__legal { max-width: 760px; margin: 22px auto 0; text-align: center; font-size: 12px; line-height: 1.5; opacity: .6; }
.lf-bs__customers { max-width: 1080px; margin: clamp(48px, 6vw, 80px) auto 0; }
.lf-bs__customers .lf-h2 { text-align: center; margin-bottom: 24px; }
@media (max-width: 749px) {
  .lf-bs__grid { grid-template-columns: 1fr; }
  .lf-bs__sources { grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); }
  .lf-bs__src { padding: 18px; }
}
/* Single combined rating: the score card fills the column height */
.lf-bs__grid { align-items: stretch; }
.lf-bs__sources, .lf-bs__src { height: 100%; }
.lf-bs__src { display: flex; flex-direction: column; justify-content: center; align-items: center; text-align: center; padding: 28px 24px; }
.lf-bs__score { font-size: clamp(52px, 6vw, 76px); }
.lf-bs__stars { font-size: 22px; margin: 14px 0 12px; }

/* Public review excerpts under the buyer summary */
.lf-rv { margin-top: clamp(36px, 5vw, 56px); }
.lf-rv__head { text-align: center; max-width: 760px; margin: 0 auto 22px; }
.lf-rv__head .lf-bs__h3 { margin-bottom: 8px; }
.lf-rv__disclaimer { margin: 0; font-size: 12.5px; line-height: 1.5; opacity: .65; }
.lf-rv__list { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 16px; align-items: start; }
.lf-rv__item { margin: 0; padding: 20px 22px; border-radius: var(--lf-radius); background: var(--lf-sec-card); }
.lf-rv__item--more { display: none; }
.lf-rv.is-open .lf-rv__item--more { display: block; }
.lf-rv__stars { display: block; font-size: 15px; letter-spacing: 2px; color: #F5B301; line-height: 1; }
.lf-rv__stars span { color: color-mix(in srgb, var(--lf-fg) 18%, transparent); }
.lf-rv__title { margin: 10px 0 0; font-weight: 600; font-size: 15px; line-height: 1.35; }
.lf-rv__text { margin: 8px 0 0; font-size: 15px; line-height: 1.55; }
.lf-rv__meta { margin: 12px 0 0; font-size: 12px; opacity: .55; }
.lf-rv__actions { text-align: center; margin-top: 8px; }
@media (max-width: 749px) {
  .lf-rv__list { grid-template-columns: 1fr; }
  .lf-rv__item { padding: 18px; }
}

import { Component } from '@theme/component';
import { getDirectionMultiplier, isMobileBreakpoint, mediaQueryLarge } from '@theme/utilities';

/**
 * @typedef {Object} LayeredSlideshowRefs
 * @property {HTMLElement} container
 * @property {HTMLElement[]} tabs
 * @property {HTMLElement[]} panels
 */

/**
 * @typedef {Object} DragState
 * @property {number} target
 * @property {number} start
 * @property {number} max
 * @property {number} activeSize - The resolved pixel size of the active panel at drag start
 * @property {1 | -1} directionMultiplier - Converts the physical pointer delta into a logical one
 * @property {boolean} left
 * @property {boolean} [dragging]
 * @property {boolean} [prevent]
 * @property {number} [progress]
 */

const DRAG_THRESHOLD = 5;
const MAX_DRAG_WIDTH_RATIO = 0.8;
const DRAG_COMPLETE_THRESHOLD = 0.5;
const INACTIVE_SIZE = 56; // Px size of inactive tabs on desktop
const INACTIVE_MOBILE_SIZE = 44; // Px size of inactive tabs on mobile
const FOCUSABLE_SELECTOR =
  'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';
const FORM_CONTROL_SELECTOR = 'input, textarea, select, [contenteditable]:not([contenteditable="false"])';

/** @extends {Component<LayeredSlideshowRefs>} */
export class LayeredSlideshowComponent extends Component {
  requiredRefs = ['container'];
  #active = 0;
  /** @type {DragState | null} */
  #drag = null;
  /** @type {AbortController | null} */
  #abort = null;
  #isMobile = false;
  /** @type {ResizeObserver | null} */
  #heightObserver = null;
  /** @type {MutationObserver | null} */
  #contentObserver = null;
  /** @type {ResizeObserver | null} */
  #containerObserver = null;

  /** @returns {number} The inactive tab size in pixels based on current viewport */
  get #inactiveSize() {
    return this.#isMobile ? INACTIVE_MOBILE_SIZE : INACTIVE_SIZE;
  }

  connectedCallback() {
    super.connectedCallback();
    const { tabs } = this.refs;
    if (!tabs?.length) return;

    this.#active = Math.max(
      0,
      tabs.findIndex((t) => t.getAttribute('aria-selected') === 'true')
    );

    this.#isMobile = isMobileBreakpoint();
    mediaQueryLarge.addEventListener('change', this.#handleMediaQueryChange);

    this.#containerObserver = new ResizeObserver((entries) => {
      for (const entry of entries) {
        if (entry.contentBoxSize) {
          // Use contentBoxSize if available for better precision, or fallback to contentRect
          const boxSize = entry.contentBoxSize[0];
          const isMobile = this.#isMobile;

          let size;
          if (boxSize) {
            size = isMobile ? boxSize.blockSize : boxSize.inlineSize;
          } else {
            size = isMobile ? entry.contentRect.height : entry.contentRect.width;
          }

          this.#updateGridSizes(size);
        }
      }
    });
    this.#containerObserver.observe(this.refs.container);

    this.#updateActiveTab();
    this.#setupEventListeners();
    this.#observeContentHeight();
  }

  #setupEventListeners() {
    this.#abort?.abort();
    this.#abort = new AbortController();
    const opts = { signal: this.#abort.signal };
    const { container, tabs } = this.refs;

    this.addEventListener('keydown', (e) => this.#handleKeydown(e), opts);

    for (const [i, tab] of tabs.entries()) {
      tab.addEventListener('click', (e) => this.#handleTabClick(e, i), opts);
      tab.addEventListener('focus', (e) => this.#handleTabFocus(e, i), opts);
    }

    this.#setupPanelFocusManagement(opts);

    if (!this.#isMobile) {
      container.addEventListener('pointerdown', (e) => this.#startDrag(e), opts);
      container.addEventListener('click', (e) => this.#preventClickDuringDrag(e), { ...opts, capture: true });
    }
  }

  #handleKeydown(/** @type {KeyboardEvent} */ e) {
    const target = /** @type {HTMLElement} */ (e.target);
    if (target.getAttribute('role') !== 'tab') return;

    const { tabs } = this.refs;
    if (!tabs) return;

    const i = tabs.indexOf(target);
    // Horizontal arrows follow reading direction; vertical (mobile) arrows don't mirror.
    const directionMultiplier = this.#isMobile ? 1 : getDirectionMultiplier(this);
    const navMap = {
      [this.#isMobile ? 'ArrowUp' : 'ArrowLeft']: -1 * directionMultiplier,
      [this.#isMobile ? 'ArrowDown' : 'ArrowRight']: 1 * directionMultiplier,
      Home: -i,
      End: tabs.length - 1 - i,
    };

    const offset = navMap[e.key];
    if (offset !== undefined) {
      e.preventDefault();
      const nextIndex = (i + offset + tabs.length) % tabs.length;
      tabs[nextIndex]?.focus();
      this.#activate(nextIndex);
    }
  }

  #handleTabClick(/** @type {MouseEvent} */ e, /** @type {number} */ index) {
    e.preventDefault();
    this.#activate(index);
  }

  #handleTabFocus(/** @type {FocusEvent} */ e, /** @type {number} */ index) {
    const target = /** @type {HTMLElement} */ (e.target);
    if (target.matches(':focus-visible')) {
      this.#activate(index);
    }
  }

  /**
   * @param {AddEventListenerOptions & { signal: AbortSignal }} opts
   */
  #setupPanelFocusManagement(opts) {
    const { panels } = this.refs;
    if (!panels) return;

    for (const [index, panel] of panels.entries()) {
      panel.addEventListener('keydown', (event) => this.#handlePanelKeydown(event, index), opts);
    }
  }

  /**
   * @param {KeyboardEvent} event
   * @param {number} index
   */
  #handlePanelKeydown(event, index) {
    if (event.key !== 'Tab') return;

    const { panels } = this.refs;
    const panel = /** @type {HTMLElement} */ (event.currentTarget);
    const focusable = this.#getFocusableElements(panel);
    const firstFocusable = focusable[0];
    const lastFocusable = focusable[focusable.length - 1];

    if (event.shiftKey) {
      const isAtStart =
        (firstFocusable && document.activeElement === firstFocusable) ||
        (!focusable.length && document.activeElement === panel);
      if (isAtStart && index > 0) {
        event.preventDefault();
        this.#activate(index - 1);
        this.#focusPanelEdge(index - 1, 'end');
      }
      return;
    }

    const isAtEnd =
      (lastFocusable && document.activeElement === lastFocusable) ||
      (!focusable.length && document.activeElement === panel);

    if (isAtEnd && panels && index < panels.length - 1) {
      event.preventDefault();
      this.#activate(index + 1);
      this.#focusPanelEdge(index + 1, 'start');
    }
  }

  /**
   * @param {number} index
   * @param {'start' | 'end'} [position]
   */
  #focusPanelEdge(index, position = 'start') {
    const panel = this.refs.panels?.[index];
    if (!panel) return;

    const focusable = this.#getFocusableElements(panel);
    const target = position === 'end' ? focusable[focusable.length - 1] : focusable[0];

    requestAnimationFrame(() => (target ?? panel).focus());
  }

  /**
   * @param {HTMLElement} panel
   * @returns {HTMLElement[]}
   */
  #getFocusableElements(panel) {
    return Array.from(panel.querySelectorAll(FOCUSABLE_SELECTOR))
      .filter((el) => !el.closest('[inert]'))
      .map((el) => /** @type {HTMLElement} */ (el));
  }

  #preventClickDuringDrag(/** @type {MouseEvent} */ e) {
    const target = /** @type {HTMLElement} */ (e.target);
    if (this.#drag?.prevent && target.closest('[role="tab"]')) {
      e.stopImmediatePropagation();
      e.preventDefault();
    }
  }

  #handleMediaQueryChange = () => {
    const wasMobile = this.#isMobile;
    this.#isMobile = isMobileBreakpoint();

    if (wasMobile !== this.#isMobile) {
      const { container } = this.refs;
      container.setAttribute('data-instant-transitions', '');

      this.#clearHeightStyles();
      // Re-calculate height first so grid calculation has correct container dimensions
      this.#observeContentHeight();
      this.#updateActiveTab();
      this.#setupEventListeners();

      requestAnimationFrame(() => {
        container.removeAttribute('data-instant-transitions');
      });
    }
  };

  disconnectedCallback() {
    super.disconnectedCallback();
    this.#abort?.abort();
    this.#heightObserver?.disconnect();
    this.#heightObserver = null;
    this.#contentObserver?.disconnect();
    this.#contentObserver = null;
    this.#containerObserver?.disconnect();
    this.#containerObserver = null;
    mediaQueryLarge.removeEventListener('change', this.#handleMediaQueryChange);
  }

  /**
   * Public method to select a slide by index
   * @param {number} index
   * @param {{ instant?: boolean }} [options]
   */
  select(index, { instant = false } = {}) {
    this.#activate(index, instant);
  }

  /**
   * @param {number} index
   * @param {boolean} [instant]
   */
  #activate(index, instant = false) {
    const { container, tabs } = this.refs;
    if (!tabs || index === this.#active || index < 0 || index >= tabs.length) return;

    if (instant) {
      container.setAttribute('data-instant-transitions', '');
    }

    this.#active = index;
    this.#updateActiveTab();

    if (instant) {
      // Double rAF to ensure layout is fully settled before re-enabling transitions
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          container.removeAttribute('data-instant-transitions');
        });
      });
    }
  }

  #updateActiveTab() {
    const { tabs, panels } = this.refs;

    for (const [i, tab] of tabs?.entries() ?? []) {
      const isActive = i === this.#active;
      tab.setAttribute('aria-selected', String(isActive));
      tab.setAttribute('tabindex', isActive ? '0' : '-1');
    }

    for (const [i, panel] of panels?.entries() ?? []) {
      const isActive = i === this.#active;
      panel.toggleAttribute('inert', !isActive);
      panel.setAttribute('tabindex', isActive ? '0' : '-1');

      const video = panel.querySelector('video');
      if (video) {
        isActive ? video.play() : video.pause();
      }
    }

    this.#updateGridSizes();
  }

  /**
   * @param {number} [containerSize] - Override container size (used during viewport switch)
   */
  #updateGridSizes(containerSize) {
    const { container, tabs } = this.refs;
    if (!tabs) return;
    const inactiveSize = this.#inactiveSize;
    const size =
      containerSize ??
      (this.#isMobile ? container.getBoundingClientRect().height : container.getBoundingClientRect().width);
    const activeSize = size - inactiveSize * (tabs.length - 1);
    const sizes = tabs.map((_, i) => (i === this.#active ? `${activeSize}px` : `${inactiveSize}px`));
    container.style.setProperty('--active-tab', sizes.join(' '));
  }

  /**
   * @param {PointerEvent} event
   */
  #startDrag(event) {
    if (this.#isMobile) return;

    const { tabs } = this.refs;
    if (!tabs) return;
    if (this.#isFormControlEvent(event)) return;

    const eventTarget = /** @type {HTMLElement} */ (event.target);
    const tab = eventTarget.closest('[role="tab"]');
    if (tab) {
      const i = tabs.indexOf(/** @type {HTMLElement} */ (tab));
      if (i === this.#active) return;
      const target = i > this.#active ? i + 1 : i;
      if (target >= tabs.length) return;

      this.#initializeDrag(event, target);
    } else {
      this.#initializeDrag(event);
    }
  }

  /**
   * Form controls need the default pointerdown action to take focus and place the caret,
   * so a press that starts on one (also inside a shadow root) never starts a drag.
   * @param {PointerEvent} event
   * @returns {boolean}
   */
  #isFormControlEvent(event) {
    for (const node of event.composedPath()) {
      if (node === this.refs.container) return false;
      if (node instanceof Element && node.matches(FORM_CONTROL_SELECTOR)) return true;
    }
    return false;
  }

  /**
   * @param {PointerEvent} event
   * @param {number} [initialTarget]
   */
  #initializeDrag(event, initialTarget) {
    const { container, tabs } = this.refs;
    if (!tabs) return;

    // Calculate active size from container dimensions
    const containerWidth = container.getBoundingClientRect().width;
    const inactiveSize = this.#inactiveSize;
    const activeSize = containerWidth - inactiveSize * (tabs.length - 1);

    this.#drag = {
      target: initialTarget ?? -1,
      start: event.clientX,
      max: containerWidth * MAX_DRAG_WIDTH_RATIO,
      activeSize,
      directionMultiplier: getDirectionMultiplier(this),
      left: initialTarget !== undefined ? initialTarget > this.#active : false,
    };

    const ac = new AbortController();
    const opts = { signal: ac.signal };

    document.addEventListener('pointermove', (e) => this.#handleDrag(e), opts);
    document.addEventListener('pointerup', () => this.#endDrag(ac), opts);
    document.addEventListener('pointercancel', () => this.#endDrag(ac), opts);

    event.preventDefault();
  }

  /**
   * @param {PointerEvent} event
   */
  #handleDrag(event) {
    if (!this.#drag) return;

    const { container, tabs } = this.refs;
    if (!container || !tabs) return;

    // Logical delta: positive always means dragging toward the previous tab in reading order.
    const delta = (event.clientX - this.#drag.start) * this.#drag.directionMultiplier;
    const move = Math.abs(delta);

    if (!this.#drag.dragging && move >= DRAG_THRESHOLD) {
      if (this.#drag.target === -1) {
        if (delta > 0 && this.#active > 0) {
          this.#drag.target = this.#active - 1;
          this.#drag.left = false;
        } else if (delta < 0 && this.#active < tabs.length - 1) {
          this.#drag.target = this.#active + 1;
          this.#drag.left = true;
        } else {
          return;
        }
      }
      this.#drag.dragging = true;
      container.setAttribute('data-dragging', '');
    }

    if (!this.#drag.dragging) return;

    const correct = this.#drag.left ? delta < 0 : delta > 0;
    const progress = correct ? Math.min(move / this.#drag.max, 1) : 0;

    const inactiveSize = this.#inactiveSize;
    const activeSize = this.#drag.activeSize;
    const range = activeSize - inactiveSize;
    const sizes = tabs.map((_, i) => {
      if (i === this.#active) {
        const active = Math.max(inactiveSize, activeSize - range * progress);
        return `${active}px`;
      }
      if (i === this.#drag?.target) {
        const drag = inactiveSize + range * progress;
        return `${drag}px`;
      }
      return `${inactiveSize}px`;
    });

    container.style.setProperty('--active-tab', sizes.join(' '));
    this.#drag.progress = progress;
  }

  /**
   * @param {AbortController} ac
   */
  #endDrag(ac) {
    if (!this.#drag) return;

    const { container } = this.refs;
    container?.removeAttribute('data-dragging');

    if (this.#drag.dragging) {
      this.#drag.prevent = true;
      setTimeout(() => (this.#drag = null), 100);

      if (this.#drag.progress && this.#drag.progress >= DRAG_COMPLETE_THRESHOLD) {
        this.#activate(this.#drag.target);
      } else {
        this.#updateActiveTab();
      }
    } else {
      this.#drag = null;
    }

    ac.abort();
  }

  #observeContentHeight() {
    const { panels } = this.refs;

    this.#heightObserver?.disconnect();
    this.#heightObserver = new ResizeObserver(() => this.#syncHeight());

    this.#contentObserver?.disconnect();
    this.#contentObserver = new MutationObserver(() => this.#syncHeight());

    for (const panel of panels ?? []) {
      const content = panel.querySelector('.layered-slideshow__content');
      const inner = content?.querySelector('.group-block-content');

      // Observe all relevant elements for resize
      if (inner) this.#heightObserver.observe(inner);
      if (content) this.#heightObserver.observe(content);

      // Observe content for DOM mutations (new blocks, text changes)
      const target = inner ?? content;
      if (target) {
        this.#contentObserver.observe(target, {
          childList: true,
          subtree: true,
          characterData: true,
        });
      }
    }

    this.#syncHeight();
  }

  #syncHeight() {
    const { container } = this.refs;
    const contentHeight = this.#getMaxContentHeight();
    const isAuto = container.getAttribute('size') === 'auto';

    if (this.#isMobile) {
      this.#syncMobileHeight(contentHeight, isAuto);
    } else {
      this.#syncDesktopHeight(contentHeight, isAuto);
    }
  }

  /**
   * @param {number} contentHeight
   * @param {boolean} isAuto
   */
  #syncDesktopHeight(contentHeight, isAuto) {
    const { container } = this.refs;

    if (isAuto) {
      // Auto mode: fit to content height
      let minHeightTemp = Math.max(contentHeight, 150);
      container.style.height = `${minHeightTemp}px`;
      this.style.minHeight = `${minHeightTemp}px`;
    } else {
      // Temporarily clear inline style to measure CSS-defined min-height
      const savedMinHeight = this.style.minHeight;
      this.style.minHeight = '';
      const cssMinHeight = parseFloat(getComputedStyle(this).minHeight) || 0;
      this.style.minHeight = savedMinHeight;

      // Only set inline heights when content exceeds CSS min-height
      if (contentHeight > cssMinHeight) {
        this.style.minHeight = `${contentHeight}px`;
        container.style.height = `${contentHeight}px`;
      } else {
        this.style.minHeight = '';
        container.style.height = '';
      }
    }
  }

  /**
   * @param {number} contentHeight
   * @param {boolean} isAuto
   */
  #syncMobileHeight(contentHeight, isAuto) {
    const { container, tabs } = this.refs;
    if (!container || !tabs) return;

    const containerStyles = getComputedStyle(container);
    const inactiveStackHeight = (tabs.length - 1) * this.#inactiveSize;

    let minPanelHeight;

    if (isAuto) {
      // Auto mode: fit to content height with reasonable minimum
      minPanelHeight = 150;
    } else {
      // CSS variable is set on component, try reading from container (inherited) or component directly
      const inheritedValue = containerStyles.getPropertyValue('--layered-panel-height-mobile');
      const componentValue = getComputedStyle(this).getPropertyValue('--layered-panel-height-mobile');
      minPanelHeight = parseFloat(inheritedValue || componentValue) || 260;
    }

    const requiredActiveHeight = Math.max(minPanelHeight, contentHeight);

    container.style.setProperty('--active-panel-height', `${requiredActiveHeight}px`);
    container.style.height = `${requiredActiveHeight + inactiveStackHeight}px`;
  }

  #clearHeightStyles() {
    const { container } = this.refs;

    this.style.minHeight = '';
    container.style.height = '';
    container.style.removeProperty('--active-panel-height');
  }

  #getMaxContentHeight() {
    const { panels } = this.refs;
    let max = 0;

    for (const panel of panels ?? []) {
      const content = panel.querySelector('.layered-slideshow__content');
      if (!content) continue;

      const inner = /** @type {HTMLElement} */ (content.querySelector('.group-block-content') ?? content);

      // Temporarily set height to auto for accurate measurement
      // This is needed because height: 100% collapses when parent has no height
      const savedHeight = inner.style.height;
      inner.style.height = 'auto';

      const styles = getComputedStyle(content);
      const paddingTop = parseFloat(styles.paddingBlockStart || styles.paddingTop) || 0;
      const paddingBottom = parseFloat(styles.paddingBlockEnd || styles.paddingBottom) || 0;

      const height = (inner.scrollHeight || 0) + paddingTop + paddingBottom;
      if (height > max) max = height;

      // Restore original height
      inner.style.height = savedHeight;
    }

    return max;
  }
}

customElements.define('layered-slideshow-component', LayeredSlideshowComponent);

import { Component } from '@theme/component';

import { morph } from '@theme/morph';
import { StandardEvents, ProductSelectEvent } from '@shopify/events';

class LocalPickup extends Component {
  /** @type {AbortController | undefined} */
  #activeFetch;

  /** @type {HTMLElement | null} */
  #pickupDrawer = null;

  connectedCallback() {
    super.connectedCallback();

    // Portal the sibling pickup drawer to document.body so its z-index
    // isn't trapped by ancestor stacking contexts on desktop.
    const drawer =
      this.nextElementSibling instanceof HTMLElement && this.nextElementSibling.matches('theme-drawer.pickup-drawer')
        ? this.nextElementSibling
        : null;
    if (drawer) {
      this.#pickupDrawer = drawer;
      document.body.appendChild(drawer);
    }

    const closestSection = this.closest(`.shopify-section, dialog`);

    /** @type {(event: ProductSelectEvent) => void} */
    const handleProductSelect = (event) => {
      if (!(event.target instanceof Element) || event.target.closest('product-card')) return;

      event.promise
        .then(({ detail }) => {
          if (!detail) return;

          const { newProduct, resource } = detail;
          if (newProduct) {
            this.dataset.productUrl = newProduct.url;
          }
          const variantId = resource ? resource.id : null;
          const variantAvailable = resource ? resource.available : null;
          if (variantId !== this.dataset.variantId) {
            if (variantId && variantAvailable) {
              this.removeAttribute('hidden');
              this.dataset.variantId = variantId;
              this.#fetchAvailability(variantId);
            } else {
              this.setAttribute('hidden', '');
            }
          }
        })
        .catch((error) => {
          if (error?.name !== 'AbortError') console.warn('[local-pickup] Event promise rejected:', error);
        });
    };

    closestSection?.addEventListener(StandardEvents.productSelect, handleProductSelect);

    this.disconnectedCallback = () => {
      closestSection?.removeEventListener(StandardEvents.productSelect, handleProductSelect);
      this.#pickupDrawer?.remove();
      this.#pickupDrawer = null;
    };
  }

  #createAbortController() {
    if (this.#activeFetch) this.#activeFetch.abort();
    this.#activeFetch = new AbortController();
    return this.#activeFetch;
  }

  /**
   * Fetches the availability of a variant.
   * @param {string} variantId - The ID of the variant to fetch availability for.
   */
  #fetchAvailability = (variantId) => {
    if (!variantId) return;

    const abortController = this.#createAbortController();

    const url = this.dataset.productUrl;
    fetch(`${url}?variant=${variantId}&section_id=${this.dataset.sectionId}`, {
      signal: abortController.signal,
    })
      .then((response) => response.text())
      .then((text) => {
        if (abortController.signal.aborted) return;

        const html = new DOMParser().parseFromString(text, 'text/html');
        const wrapper = html.querySelector(`local-pickup[data-variant-id="${variantId}"]`);
        if (wrapper) {
          this.removeAttribute('hidden');
          morph(this, wrapper);

          // Update the portaled drawer with fresh content from the server.
          // If the page originally loaded on an unavailable variant the drawer
          // wasn't rendered (can_add_to_cart was false), so portal it now.
          // Resolve via the sibling relationship to avoid colliding with
          // other buy-buttons blocks on the same page.
          const newDrawer =
            wrapper.nextElementSibling instanceof HTMLElement &&
            wrapper.nextElementSibling.matches('theme-drawer.pickup-drawer')
              ? wrapper.nextElementSibling
              : null;
          if (newDrawer) {
            if (this.#pickupDrawer) {
              morph(this.#pickupDrawer, newDrawer);
            } else {
              this.#pickupDrawer = newDrawer;
              document.body.appendChild(this.#pickupDrawer);
            }
          }
        } else {
          this.setAttribute('hidden', '');
        }
      })
      .catch((_e) => {
        if (abortController.signal.aborted) return;
        this.setAttribute('hidden', '');
      });
  };
}

if (!customElements.get('local-pickup')) {
  customElements.define('local-pickup', LocalPickup);
}

import { Component } from '@theme/component';
import { isClickedOutside, normalizeString, onAnimationEnd } from '@theme/utilities';

/**
 * A custom element that displays a localization form.
 *
 * @typedef {object} FormRefs
 * @property {HTMLDivElement} countryList - The country list element.
 * @property {HTMLInputElement} countryInput - The country input element.
 * @property {HTMLUListElement[]} countryListItems - The country list items element.
 * @property {HTMLFormElement} form - The form element.
 * @property {HTMLDivElement} liveRegion - The live region element.
 * @property {HTMLSelectElement} languageInput - The language input element.
 * @property {HTMLSpanElement} noResultsMessage - The no results message element.
 * @property {HTMLUListElement} popularCountries - The popular countries element.
 * @property {HTMLInputElement} search - The search input element.
 * @property {HTMLButtonElement} resetButton - The reset button element.
 *
 * @extends {Component<FormRefs>}
 */
class LocalizationFormComponent extends Component {
  connectedCallback() {
    super.connectedCallback();

    this.refs.search && this.refs.search.addEventListener('keydown', this.#onSearchKeyDown);
    this.refs.countryList && this.refs.countryList.addEventListener('keydown', this.#onContainerKeyDown);
    this.refs.countryList && this.refs.countryList.addEventListener('scroll', this.#onCountryListScroll);

    // Resizing the language input can be expensive for browsers that don't support field-sizing: content.
    // Spliting it into separate tasks at least helps when there are multiple localization forms on the page.
    setTimeout(() => this.resizeLanguageInput(), 0);
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this.refs.search && this.refs.search.removeEventListener('keydown', this.#onSearchKeyDown);
    this.refs.countryList && this.refs.countryList.removeEventListener('keydown', this.#onContainerKeyDown);
    this.refs.countryList && this.refs.countryList.removeEventListener('scroll', this.#onCountryListScroll);
  }

  /**
   * Handles the keydown event for the container.
   *
   * @param {KeyboardEvent} event - The event object.
   */
  #onContainerKeyDown = (event) => {
    const { countryInput, countryListItems, form } = this.refs;

    switch (event.key) {
      case 'ArrowUp':
        event.preventDefault();
        event.stopPropagation();
        this.#changeCountryFocus('UP');
        break;
      case 'ArrowDown':
        event.preventDefault();
        event.stopPropagation();
        this.#changeCountryFocus('DOWN');
        break;
      case 'Enter': {
        event.preventDefault();
        event.stopPropagation();
        const focusedItem = countryListItems.find((item) => item.getAttribute('aria-selected') === 'true');

        if (focusedItem) {
          countryInput.value = focusedItem.dataset.value ?? '';
          form.submit();
        }
        break;
      }
    }

    if (!this.refs.search) return;

    setTimeout(() => {
      const focusableItems = this.refs.countryListItems.filter((item) => !item.hasAttribute('hidden'));
      const focusedItemIndex = focusableItems.findIndex((item) => item === document.activeElement);
      const focusedItem = focusableItems[focusedItemIndex];

      if (focusedItem) {
        this.refs.search.setAttribute('aria-activedescendant', focusedItem.id);
      } else {
        this.refs.search.setAttribute('aria-activedescendant', '');
      }
    });
  };

  /**
   * Selects a country.
   *
   * @param {string} countryName - The name of the country to select.
   * @param {Event} event - The event object.
   */
  selectCountry = (countryName, event) => {
    event.preventDefault();
    const { countryInput, form } = this.refs;

    countryInput.value = countryName;
    form?.submit();
  };

  /**
   * Changes the language of the localization form.
   *
   * @param {Event} event - The event object.
   */
  changeLanguage(event) {
    const { form, languageInput } = this.refs;
    const value = event.target instanceof HTMLSelectElement ? event.target.value : null;

    if (value) {
      languageInput.value = value;
      this.resizeLanguageInput();
      form.submit();
    }
  }

  resizeLanguageInput() {
    const { languageInput } = this.refs;

    if (!languageInput || CSS.supports('field-sizing', 'content')) return;

    // Hide all options except the selected option
    for (const option of languageInput.options) {
      if (!option.selected) {
        option.dataset.optionLabel = option.textContent || '';
        option.innerText = '';
      }
    }

    // Calculate the width of the select element (which is based on the width of the widest option)
    languageInput.style.width = 'fit-content';
    const originalElementWidth = `${Math.ceil(languageInput.offsetWidth) + 1}px`;

    // Fix the width of the select element
    if (languageInput.offsetWidth > 0) {
      languageInput.style.width = originalElementWidth;
    }

    // Add back all option labels
    for (const option of languageInput.options) {
      if (option.dataset.optionLabel) {
        option.textContent = option.dataset.optionLabel;
        delete option.dataset.optionLabel;
      }
    }
  }

  /**
   * Finds matches for a given search value in a country element.
   *
   * @typedef {Object} Options
   * @property {boolean} [matchLabel] - Whether to match the label.
   * @property {boolean} [matchAlias] - Whether to match the alias.
   * @property {boolean} [matchIso] - Whether to match the iso.
   * @property {boolean} [matchCurrency] - Whether to match the currency.
   * @property {boolean} [labelMatchStart] - Whether to match the label start.
   * @property {boolean} [aliasExactMatch] - Whether to match the alias exact match.
   *
   * @typedef {Object} MatchTypes
   * @property {boolean} [label] - Whether the label matches the search value.
   * @property {boolean} [alias] - Whether the alias matches the search value.
   * @property {boolean} [iso] - Whether the iso matches the search value.
   * @property {boolean} [currency] - Whether the currency matches the search value.
   *
   * @param {string} searchValue - The search value to find matches for.
   * @param {HTMLElement} countryEl - The country element to find matches in.
   * @param {Options} options - The options for the search.
   * @returns {MatchTypes} The matches found in the country element.
   */
  #findMatches(
    searchValue,
    countryEl,
    options = {
      // Which data types (label, alias, iso) to match against
      matchLabel: true,
      matchAlias: true,
      matchIso: true,
      matchCurrency: true,
      // If true, the search value must match the start of the label
      labelMatchStart: false,
      // If true, a result will not display unless the search value equals an alias in its entirety
      aliasExactMatch: false,
    }
  ) {
    let matchTypes = {};
    const { aliases, value: iso } = countryEl.dataset;

    if (options.matchLabel) {
      const countryName = normalizeString(countryEl.querySelector('.country')?.textContent ?? '');

      if (!countryName) return matchTypes;

      matchTypes.label = options.labelMatchStart
        ? countryName.startsWith(searchValue)
        : countryName.includes(searchValue);
    }

    if (options.matchCurrency) {
      const currency = normalizeString(countryEl.querySelector('.localization-form__currency')?.textContent ?? '');
      matchTypes.currency = currency.includes(searchValue);
    }

    if (options.matchIso) {
      matchTypes.iso = normalizeString(iso ?? '') == searchValue;
    }

    if (options.matchAlias) {
      const countryAliases = aliases?.split(',').map((alias) => normalizeString(alias));

      if (!countryAliases) return matchTypes;

      matchTypes.alias =
        countryAliases.length > 0 &&
        countryAliases.find((alias) =>
          options.aliasExactMatch ? alias === searchValue : alias.startsWith(searchValue)
        ) !== undefined;
    }

    return matchTypes;
  }

  /**
   * Highlights matching text in a string by wrapping it in <mark> tags.
   *
   * @param {string | null} text - The text to highlight.
   * @param {string} searchValue - The search value to highlight.
   * @returns {string} The text with matching parts wrapped in <mark> tags.
   */
  #highlightMatches(text, searchValue) {
    if (!text || !searchValue) return text ?? '';

    const normalizedText = normalizeString(text);
    const normalizedSearch = normalizeString(searchValue);
    const startIndex = normalizedText.indexOf(normalizedSearch);

    if (startIndex === -1) return text;

    const endIndex = startIndex + normalizedSearch.length;
    const before = text.slice(0, startIndex);
    const match = text.slice(startIndex, endIndex);
    const after = text.slice(endIndex);

    let result = '';
    if (before) {
      result += `<mark>${before}</mark>`;
    }
    result += match;
    if (after) {
      result += `<mark>${after}</mark>`;
    }
    return result;
  }

  /**
   * Filters the countries based on the search value.
   */
  filterCountries() {
    const { countryList, countryListItems, liveRegion, noResultsMessage, popularCountries, resetButton, search } =
      this.refs;
    const { labelResultsCount } = this.dataset;
    const searchValue = normalizeString(search.value);
    let countVisibleCountries = 0;

    resetButton.toggleAttribute('hidden', !searchValue);

    const wrapper = this.querySelector('.country-selector-form__wrapper');
    if (wrapper) {
      wrapper.classList.toggle('is-searching', !!searchValue);
    }

    for (const countryEl of countryListItems) {
      if (searchValue === '') {
        countryEl.removeAttribute('hidden');
        const countrySpan = countryEl.querySelector('.country');
        if (countrySpan) {
          // eslint-disable-next-line no-self-assign
          countrySpan.textContent = countrySpan.textContent;
        }
        countVisibleCountries++;
      } else {
        const matches = this.#findMatches(searchValue, countryEl);

        // In the future, we could reorder/rank filtered results based on the match types
        if (matches.label || matches.alias || matches.iso || matches.currency) {
          countryEl.removeAttribute('hidden');
          const countrySpan = countryEl.querySelector('.country');
          if (countrySpan) {
            countrySpan.innerHTML = this.#highlightMatches(countrySpan.textContent, searchValue);
          }
          countVisibleCountries++;
        } else {
          countryEl.setAttribute('hidden', '');
        }
      }
    }

    // Popular countries are only listed in their own list, so it stays visible while it still has a match.
    if (popularCountries) {
      const hasVisiblePopularCountry = Array.from(popularCountries.children).some(
        (country) => !country.hasAttribute('hidden')
      );

      popularCountries.toggleAttribute('hidden', !hasVisiblePopularCountry);
    }

    if (liveRegion && labelResultsCount) {
      liveRegion.innerText = labelResultsCount.replace('[count]', `${countVisibleCountries}`);
    }

    noResultsMessage.hidden = countVisibleCountries > 0;
    countryList.scrollTop = 0;
  }

  /**
   * Changes the focus of the country list items.
   *
   * @param {string} direction - The direction to change the focus.
   */
  #changeCountryFocus(direction) {
    const { countryListItems } = this.refs;
    const focusableItems = countryListItems.filter((item) => !item.hasAttribute('hidden'));
    const focusedItemIndex = focusableItems.findIndex((item) => item === document.activeElement);
    const focusedItem = focusableItems[focusedItemIndex];
    let itemToFocus;

    if (direction === 'UP') {
      itemToFocus =
        focusedItemIndex > 0 ? focusableItems[focusedItemIndex - 1] : focusableItems[focusableItems.length - 1];
    } else {
      itemToFocus =
        focusedItemIndex < focusableItems.length - 1 ? focusableItems[focusedItemIndex + 1] : focusableItems[0];
    }

    if (focusedItem) {
      focusedItem.setAttribute('aria-selected', 'false');
    }
    itemToFocus?.setAttribute('aria-selected', 'true');
    itemToFocus?.focus();
  }

  /**
   * Resets the countries filter.
   *
   * @param {Event} event - The event object.
   */
  resetCountriesFilter(event) {
    const { search } = this.refs;

    event.stopPropagation();
    search.value = '';
    this.filterCountries();
    search.setAttribute('aria-activedescendant', '');
    search.focus();
  }

  /**
   * Handles the keydown event for the search input.
   *
   * @param {KeyboardEvent} event - The event object.
   */
  #onSearchKeyDown = (event) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    this.#onContainerKeyDown(event);
  };

  /**
   * Resets the form.
   */
  resetForm() {
    const { search } = this.refs;

    if (!search) return;

    if (search.value != '') {
      search.value = '';
      this.filterCountries();
      search.setAttribute('aria-activedescendant', '');
    }
  }

  /**
   * Focuses the search input.
   */
  focusSearchInput = () => {
    const { search } = this.refs;

    search?.focus();
  };

  /**
   * Handles the scroll event on the country list.
   *
   * @param {Event} event - The scroll event object.
   */
  #onCountryListScroll = (event) => {
    const countryFilter = this.querySelector('.country-filter');
    const countryList = event.target instanceof HTMLElement ? event.target : null;

    if (countryFilter && countryList) {
      const shouldShowBorder = countryList.scrollTop > 0;
      countryFilter.classList.toggle('is-scrolled', shouldShowBorder);
    }
  };
}

/**
 * A custom element that displays a dropdown localization form.
 *
 * @typedef {object} DropdownRefs
 * @property {HTMLButtonElement} button - The button element.
 * @property {HTMLDivElement} panel - The panel element.
 * @property {LocalizationFormComponent} localizationForm - The localization form component.
 *
 * @extends {Component<DropdownRefs>}
 */
class DropdownLocalizationComponent extends Component {
  get isHidden() {
    return this.refs.panel.hasAttribute('hidden');
  }

  /**
   * Toggles the panel.
   */
  toggleSelector() {
    return this.isHidden ? this.showPanel() : this.hidePanel();
  }

  /**
   * Shows the panel.
   */
  showPanel() {
    if (!this.isHidden) return;

    this.addEventListener('keyup', this.#handleKeyUp);
    document.addEventListener('click', this.#handleClickOutside);

    this.refs.panel.removeAttribute('hidden');
    this.refs.button.setAttribute('aria-expanded', 'true');

    onAnimationEnd(this.refs.panel, () => {
      this.#updateWidth();
      this.refs.localizationForm?.focusSearchInput();
    });
  }

  /**
   * Hides the panel.
   */
  hidePanel = () => {
    if (this.isHidden) return;

    this.removeEventListener('keyup', this.#handleKeyUp);
    document.removeEventListener('click', this.#handleClickOutside);

    this.refs.button?.setAttribute('aria-expanded', 'false');
    this.refs.panel.setAttribute('hidden', '');
    this.refs.localizationForm?.resetForm();
  };

  /**
   * Handles the click outside event.
   *
   * @param {PointerEvent} event - The event object.
   */
  #handleClickOutside = (event) => {
    if (isClickedOutside(event, this)) {
      this.hidePanel();
    }
  };

  /**
   * Updates the width of the panel.
   */
  #updateWidth() {
    this.style.setProperty('--width', `${this.refs.localizationForm.offsetWidth}px`);
  }

  /**
   * Handles the keyup event.
   *
   * @param {KeyboardEvent} event - The event object.
   */
  #handleKeyUp = (event) => {
    switch (event.key) {
      case 'Escape':
        this.hidePanel();
        event.stopPropagation();
        this.refs.button?.focus();
        break;
    }
  };
}

/**
 * A custom element that displays a drawer localization form.
 *
 * @typedef {object} DrawerRefs
 * @property {HTMLDialogElement} dialog - The dialog element.
 * @property {LocalizationFormComponent} localizationForm - The localization form component.
 *
 * @extends {Component<DrawerRefs>}
 */
class DrawerLocalizationComponent extends Component {
  /**
   * Toggles the dialog.
   *
   * @param {ToggleEvent} event - The event object.
   */
  toggle(event) {
    const { target } = event;
    const { localizationForm } = this.refs;

    if (!localizationForm || !(target instanceof HTMLDetailsElement)) return;

    const countryList = localizationForm.querySelector('.country-selector-form__wrapper');

    if (target.open) {
      if (countryList) countryList.addEventListener('scroll', this.#onCountryListScroll);
      onAnimationEnd(target, localizationForm.focusSearchInput);
    } else {
      countryList?.removeEventListener('scroll', this.#onCountryListScroll);
      localizationForm.resetForm();
    }
  }

  /**
   * Handles the scroll event on the country list.
   *
   * @param {Event} event - The scroll event object.
   */
  #onCountryListScroll = (event) => {
    const countryFilter = this.querySelector('.country-filter');
    const countryList = event.target instanceof HTMLElement ? event.target : null;

    if (countryFilter && countryList) {
      const shouldShowBorder = countryList.scrollTop > 0;
      countryFilter.classList.toggle('is-scrolled', shouldShowBorder);
    }
  };
}

