  this.moduleCount = 0;
  /** @type {number[]|null} */
  this.dataCache = null;
  /** @type {QR8bitByte[]} */
  this.dataList = [];
}

QRCodeModel.prototype = {
  /**
   * Add data
   *
   * @param {string} data
   */
