      if (row === undefined) continue;
      row[(i % 3) + this.moduleCount - 8 - 3] = mod;
    }
    for (var i = 0; i < 18; i++) {
      var mod = !test && ((bits >> i) & 1) == 1;
      var row = this.modules[(i % 3) + this.moduleCount - 8 - 3];
      if (row === undefined) continue;
      row[Math.floor(i / 3)] = mod;
    }
