  /**
   * @param {number[]} data
   * @param {number} maskPattern
   */
  mapData: function (data, maskPattern) {
    if (this.modules == null) {
      return;
    }
    var inc = -1;
    var row = this.moduleCount - 1;
    var bitIndex = 7;
    var byteIndex = 0;
    for (var col = this.moduleCount - 1; col > 0; col -= 2) {
      if (col == 6) col--;
