            if (mask) {
              dark = !dark;
            }
            var rowR = this.modules[row];
            if (rowR !== undefined) {
              rowR[col - c] = dark;
            }
            bitIndex--;
            if (bitIndex == -1) {
              byteIndex++;
              bitIndex = 7;
            }
          }
